Class Contador
  Private Define valor As Integer;

  Method Constructor(inicial As Integer)
    This.valor <- inicial;
  EndMethod

  Method Actual() As Integer
    Return This.valor;
  EndMethod
EndClass

Algorithm Crear
  Write New Contador(10).Actual();
EndAlgorithm

Class Punto
  Define x As Integer;
EndClass

Algorithm SinNuevo
  Define p As Punto;
  p.x <- 1;
EndAlgorithm
